def emit_unit(path):
    raw = open(path, encoding="utf-8").read()
    m = re.match(r"^---\n(.*?)\n---\n", raw, re.S)
    return m.group(1) if m else ""

OUT = []
problems = []
for u in UNITS:
    fm = emit_unit(u["file"])
    lines = ["---", fm, "---", ""]
    im = re.search(r'^icon:\s*"([^"]*)"', fm, re.M)
    cm = re.search(r'^color:\s*"([^"]*)"', fm, re.M)
    for (title, desc, zh, en, alt, srs) in u["lessons"]:
        lines.append("---")
        lines.append(f'lessonTitle: "{title}"')
        lines.append(f'description: "{desc}"')
        lines.append(f'icon: "{im.group(1)}"')
        lines.append(f'color: "{cm.group(1)}"')
        lines.append("---")
        lines.append("")
        lines.append("[writing]")
        lines.append('text: "Write this passage in English"')
        lines.append(f'sentence: "{zh}（字数80-100）"')
        lines.append(f'answer: "{en}"')
        lines.append(f'acceptAlso: "{alt}"')
        lines.append(f'srsWords: {srs}')
        lines.append("")
    open(u["file"], "w", encoding="utf-8").write("\n".join(lines))
    for (title, desc, zh, en, alt, srs) in u["lessons"]:
        for (label, txt) in [("answer", en), ("acceptAlso", alt)]:
            w = wc(txt)
            if not (80 <= w <= 100):
                problems.append(f"{u['file']} | {title} | {label} = {w}")

print("WROTE", len(UNITS), "units")
print("PROBLEMS:", len(problems))
for p in problems:
    print("  ", p)
